import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def cents(text):
    return int((Decimal(text.strip()) * 100).to_integral_value())


def pnum(text):
    digits = re.sub(r"\D", "", text or "")
    return int(digits) if digits else 0


def pdate(text):
    return date.fromisoformat(text.strip())


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def parse_offset(text):
    text = text.strip()
    sign = -1 if text.startswith("-") else 1
    hours, minutes = text.lstrip("+-").split(":")
    return sign * (int(hours) * 60 + int(minutes))


def parse_instant(text):
    text = text.strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    parsed = datetime.fromisoformat(text)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc).replace(tzinfo=None)


def main(input_dir, output_file):
    conf = configparser.ConfigParser(interpolation=None)
    conf.optionxform = str.lower
    with open(os.path.join(input_dir, "policy.ini"), encoding="utf-8-sig") as handle:
        conf.read_file(handle)
    library = conf["statement"]["library"].strip()
    period_start = pdate(conf["statement"]["period_start"])
    period_end = pdate(conf["statement"]["period_end"])

    base_offset = parse_offset(conf["clock"].get("offset", "+00:00"))
    changes = []
    for part in conf["clock"].get("changes", "").split(";"):
        part = part.strip()
        if part:
            instant, offset = part.split()
            changes.append((parse_instant(instant), parse_offset(offset)))
    changes.sort()

    def local_time(instant):
        offset = base_offset
        for when, new_offset in changes:
            if instant >= when:
                offset = new_offset
        return instant + timedelta(minutes=offset)

    items = {}
    categories = {}
    for section in conf.sections():
        kind, _, name = section.partition(":")
        sec = conf[section]
        if kind == "item":
            items[name.strip().lower()] = {
                "name": name.strip(),
                "loan_days": int(sec["loan_days"]),
                "renewals": int(sec["renewals"]),
                "grace": int(sec["grace_days"]),
                "daily": cents(sec["daily"]),
                "cap": cents(sec["loan_cap"]),
            }
        elif kind == "category":
            cap = sec["statement_cap"].strip()
            categories[name.strip().lower()] = {
                "name": name.strip(),
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(sec["discount"]),
                "exempt": {x.strip().lower() for x in sec.get("exempt", "").split(",") if x.strip()},
            }

    branches = read_csv(os.path.join(input_dir, "branches.csv"))
    branch_ids = [row["branch"].strip() for row in branches]
    branch_lookup = {b.lower(): b for b in branch_ids}
    open_days = {}
    for row in branches:
        open_days[row["branch"].strip()] = {
            d.strip().lower()[:3] for d in row["open_days"].split()}

    cal_branch = {}
    cal_star = {}
    for row in read_csv(os.path.join(input_dir, "calendar.csv")):
        text = row["date"].strip()
        if ".." in text:
            first, last = text.split("..")
        else:
            first = last = text
        first, last = pdate(first), pdate(last)
        status = row["status"].strip().lower()
        target = row["branch"].strip()
        bucket = cal_star if target == "*" else cal_branch.setdefault(
            branch_lookup.get(target.lower(), target), [])
        if target == "*":
            cal_star.setdefault("rows", []).append((first, last, status))
        else:
            bucket.append((first, last, status))

    def is_open(branch, day):
        for first, last, status in cal_branch.get(branch, []):
            if first <= day <= last:
                return status == "open"
        for first, last, status in cal_star.get("rows", []):
            if first <= day <= last:
                return status == "open"
        return WEEKDAYS[day.weekday()] in open_days.get(branch, set())

    def next_open(branch, day):
        for _ in range(3700):
            if is_open(branch, day):
                return day
            day += timedelta(days=1)
        return day

    patron_rows = {}
    for row in read_csv(os.path.join(input_dir, "patrons.csv")):
        patron_rows.setdefault(pnum(row["patron"]), []).append(
            (pdate(row["since"]), row["patron"].strip(), row["category"].strip()))
    for rows in patron_rows.values():
        rows.sort()

    def category_on(patron, day):
        chosen = None
        for since, _, category in patron_rows.get(patron, []):
            if since <= day:
                chosen = category
        if chosen is None:
            chosen = patron_rows[patron][0][2]
        return categories[chosen.lower()]

    waivers = {}
    for row in read_csv(os.path.join(input_dir, "waivers.csv")):
        if row["status"].strip().lower() != "active":
            continue
        value = row["value"].strip()
        amount = None if value.lower() == "full" else cents(value)
        waivers.setdefault(pnum(row["patron"]), []).append((row["loan"].strip(), amount))

    events = {}
    export_dir = os.path.join(input_dir, "exports")
    for name in sorted(os.listdir(export_dir)):
        path = os.path.join(export_dir, name)
        lower = name.lower()
        if lower.endswith(".csv"):
            for row in read_csv(path):
                row = {k: (v or "").strip() for k, v in row.items() if k}
                row["_local"] = datetime.strptime(row["time"], "%Y-%m-%d %H:%M")
                events.setdefault(row["event"], row)
        elif lower.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as handle:
                for line in handle:
                    line = line.strip()
                    if not line:
                        continue
                    row = {k: ("" if v is None else str(v).strip()) for k, v in json.loads(line).items()}
                    row["_local"] = local_time(parse_instant(row["at"]))
                    events.setdefault(row["event"], row)

    cancelled = {ev["target"] for ev in events.values() if ev.get("type", "").lower() == "void"}
    checkouts = {}
    later = {}
    for ev in events.values():
        kind = ev.get("type", "").lower()
        if ev["event"] in cancelled or kind == "void":
            continue
        if kind == "checkout":
            checkouts[ev["loan"]] = ev
        elif kind in ("renew", "return"):
            later.setdefault(ev["loan"], []).append(ev)

    def branch_of(ev):
        text = ev.get("branch", "")
        return branch_lookup.get(text.lower(), text)

    loans = []
    for loan_id, co in checkouts.items():
        checkout = co["_local"].date()
        if checkout > period_end:
            continue
        item = items[co["item_type"].lower()]
        branch = branch_of(co)
        due = next_open(branch, checkout + timedelta(days=item["loan_days"]))
        renewals = 0
        returned = None
        for ev in sorted(later.get(loan_id, []), key=lambda e: e["_local"]):
            day = ev["_local"].date()
            if ev["type"].lower() == "return":
                returned = day
                if ev.get("via", "").lower() == "dropbox":
                    returned = day - timedelta(days=1)
                break
            if day <= due and renewals < item["renewals"] and day <= period_end:
                renewals += 1
                due = next_open(branch, day + timedelta(days=item["loan_days"]))
        if returned is not None and returned < period_start:
            continue
        if returned is not None and returned > period_end:
            returned = None
        end_day = returned if returned is not None else period_end
        overdue = 0
        day = due + timedelta(days=1)
        while day <= end_day:
            if is_open(branch, day):
                overdue += 1
            day += timedelta(days=1)
        if overdue == 0:
            continue
        charged = overdue if overdue > item["grace"] else 0
        category = category_on(pnum(co["patron"]), checkout)
        base = charged * item["daily"]
        if item["name"].lower() in category["exempt"]:
            base = 0
        base = min(base, item["cap"])
        assessed = (base * (100 - category["discount"]) * 2 + 100) // 200
        patron = pnum(co["patron"])
        applying = [w for w in waivers.get(patron, []) if w[0] == "*" or w[0] == loan_id]
        if any(amount is None for _, amount in applying):
            waived = assessed
        else:
            waived = min(assessed, sum(amount for _, amount in applying))
        loans.append({
            "patron": patron, "loan": loan_id, "item": co["item"], "item_type": item["name"],
            "branch": branch, "checkout": checkout.isoformat(), "due": due.isoformat(),
            "returned": returned.isoformat() if returned else None,
            "overdue_days": overdue, "charged_days": charged, "assessed": assessed,
            "waived": waived, "capped": 0, "net": assessed - waived})

    by_patron = {}
    for loan in loans:
        by_patron.setdefault(loan["patron"], []).append(loan)

    statements = []
    for patron in sorted(by_patron):
        group = by_patron[patron]
        category = category_on(patron, period_end)
        if category["cap"] is not None:
            excess = sum(l["net"] for l in group) - category["cap"]
            if excess > 0:
                order = sorted(group, key=lambda l: (l["due"], l["loan"]), reverse=True)
                for loan in order:
                    take = min(excess, loan["net"])
                    loan["capped"] = take
                    excess -= take
                    if excess <= 0:
                        break
        group.sort(key=lambda l: (l["due"], l["loan"]))
        out_loans = []
        for loan in group:
            loan["billed"] = loan["net"] - loan["capped"]
            out_loans.append({k: loan[k] for k in (
                "loan", "item", "item_type", "branch", "checkout", "due", "returned",
                "overdue_days", "charged_days", "assessed", "waived", "capped", "billed")})
        entry = {"patron": sorted(patron_rows[patron])[-1][1], "category": category["name"],
                 "loans": out_loans}
        for key in ("assessed", "waived", "capped", "billed"):
            entry[key] = sum(l[key] for l in out_loans)
        statements.append(entry)

    summary = []
    for branch in branch_ids:
        mine = [l for l in loans if l["branch"] == branch]
        row = {"branch": branch, "loans": len(mine)}
        for key in ("charged_days", "assessed", "waived", "capped", "billed"):
            row[key] = sum(l[key] for l in mine)
        summary.append(row)

    result = {"library": library,
              "period": {"start": period_start.isoformat(), "end": period_end.isoformat()},
              "statements": statements, "branches": summary}
    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump(result, handle, indent=1, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
